"""Small CMSIS-SVD data reader and validation layer.

The model keeps optional properties distinct from explicit zeroes, and retains
source positions so that diagnostics can explain nested register descriptions.
"""
from dataclasses import dataclass, field as dc_field
import re
import xml.parsers.expat as expat


class Failure(Exception):
    def __init__(self, title, causes=()):
        self.title = title
        self.causes = list(causes)
        super().__init__(title)


class ParseIssue(Exception):
    def __init__(self, messages, nested=False):
        self.messages = messages if isinstance(messages, list) else [messages]
        self.nested = nested


@dataclass
class Node:
    tag: str
    attrs: dict = dc_field(default_factory=dict)
    children: list = dc_field(default_factory=list)
    text: str = ''
    line: int = 1
    col: int = 1

    def child(self, tag):
        return next((n for n in self.children if n.tag == tag), None)

    def all(self, tag):
        return [n for n in self.children if n.tag == tag]

    def get(self, tag, default=None):
        n = self.child(tag)
        return n.text.strip() if n is not None else default


def xml_tree(data):
    roots = []
    stack = []
    parser = expat.ParserCreate()
    def start(tag, attrs):
        n = Node(tag.split(':')[-1], attrs, line=parser.CurrentLineNumber,
                 col=parser.CurrentColumnNumber + 1)
        if stack:
            stack[-1].children.append(n)
        else:
            roots.append(n)
        stack.append(n)
    def end(tag):
        stack.pop()
    def text(t):
        if stack:
            stack[-1].text += t
    parser.StartElementHandler = start
    parser.EndElementHandler = end
    parser.CharacterDataHandler = text
    try:
        parser.Parse(data, True)
    except expat.ExpatError as e:
        line, col = e.lineno, e.offset + 1
        msg = str(e).split(': line')[0]
        if 'no element found' in msg and not roots:
            msg = 'the document does not have a root node'
        elif 'syntax error' in msg or 'invalid token' in msg:
            msg = f'unknown token at {line}:{col}'
        elif 'no element found' in msg:
            tag = stack[-1].tag if stack else (roots[-1].tag if roots else 'device')
            msg = f'the root node was opened but never closed'
        elif 'mismatched tag' in msg:
            source = data.decode('utf-8', 'replace') if isinstance(data, bytes) else data
            rows = source.splitlines()
            tail = rows[line-1][col-1:] if line <= len(rows) else ''
            m = re.search(r'</([^>]+)>', tail)
            found = m.group(1) if m else ''
            expected = stack[-1].tag if stack else ''
            msg = f"expected '{expected}' tag, not '{found}' at {line}:{col}"
        elif 'junk after document element' in msg:
            msg = f'unknown token at {line}:{col}'
        else:
            msg = f'{msg} at {line}:{col}'
        raise Failure('Error parsing SVD XML file', [msg])
    return roots[0] if roots else None


ENUMS = {
    'access': ('read-only','write-only','read-write','writeOnce','read-writeOnce'),
    'modifiedWriteValues': ('oneToClear','oneToSet','oneToToggle','zeroToClear','zeroToSet','zeroToToggle','clear','set','modify'),
    'readAction': ('clear','set','modify','modifyExternal'),
    'usage': ('read','write','read-write'),
    'endian': ('little','big','selectable','other'),
}
PROP_NUM = ('size','resetValue','resetMask')
PROP_STR = ('access',)


class Reader:
    def __init__(self, strict=False):
        self.strict = strict

    def parsing(self, n):
        name = n.get('name')
        return f'Parsing {n.tag} `{name}` at {n.line}:{n.col}' if name is not None else f'Parsing unknown {n.tag} at {n.line}:{n.col}'

    def context(self, n):
        name = n.get('name')
        return f'In {n.tag} `{name}`' if name is not None else f'In unknown {n.tag}'

    def entity(self, n, func):
        try:
            return func(n)
        except ParseIssue as e:
            prefix = self.context(n) if e.nested else self.parsing(n)
            raise ParseIssue([prefix] + e.messages, True)

    def required(self, n, tag):
        v = n.get(tag)
        if v is None:
            raise ParseIssue(f'Expected a <{tag}> tag, found none')
        return v

    def name(self, n):
        name = self.required(n, 'name')
        if self.strict:
            if not re.fullmatch(r'[A-Za-z0-9_\[\]%]+', name):
                raise ParseIssue(f'`Name check error: Name `{name}` contains unexpected symbol')
        return name

    def number_text(self, s, bits=64):
        s = s.strip()
        if s.startswith('#'):
            s = '0b' + s[1:]
        try:
            if not s:
                raise ValueError('cannot parse integer from empty string')
            if '_' in s or s.startswith('-'):
                raise ValueError('invalid digit found in string')
            if s.lower().startswith('0x'):
                val = int(s[2:], 16)
            elif s.lower().startswith('0b'):
                val = int(s[2:].replace('x', '0').replace('X', '0'), 2)
            else:
                val = int(s, 10)
            if val < 0:
                raise ValueError('invalid digit found in string')
            if val >= (1 << bits):
                raise ValueError('number too large to fit in target type')
            return val
        except (ValueError, OverflowError) as e:
            reason = str(e)
            if reason not in ('cannot parse integer from empty string','number too large to fit in target type'):
                reason = 'invalid digit found in string'
            raise ParseIssue(f'Failed to parse `{reason}`')

    def num(self, n, tag, default=None, required=False, bits=32):
        el = n.child(tag)
        if el is None:
            if required:
                self.required(n, tag)
            return default
        return self.entity(el, lambda e: self.number_text(e.text, bits))

    def boolean(self, n, tag, default=None, required=False):
        el=n.child(tag)
        if el is None:
            if required:self.required(n,tag)
            return default
        def f(e):
            if e.text.strip() in ('true','1'):return True
            if e.text.strip() in ('false','0'):return False
            raise ParseIssue('Failed to parse `provided string was not `true` or `false``')
        return self.entity(el,f)

    def enum(self, n, tag):
        el=n.child(tag)
        if el is None:return None
        v=el.text.strip()
        if v not in ENUMS[tag]:
            def fail(e):raise ParseIssue(f"unknown {tag} variant '{v}' found")
            return self.entity(el,fail)
        return v

    def props(self, n):
        out={}
        for key in PROP_NUM:
            v=self.num(n,key,bits=64 if key!='size' else 32)
            if v is not None:out[key]=v
        for key in PROP_STR:
            v=self.enum(n,key)
            if v is not None:out[key]=v
        return out

    def dims(self, n, out):
        dim=self.num(n,'dim')
        if dim is None:return
        inc=self.num(n,'dimIncrement',required=True)
        idx=n.get('dimIndex')
        if idx is None:
            indexes=[str(i) for i in range(min(dim,65536))]
        elif ',' in idx:
            indexes=[s.strip() for s in idx.split(',')]
        elif '-' in idx:
            bounds=idx.split('-')
            try:
                a,b=bounds
                if a.isdecimal() and b.isdecimal():indexes=[str(i) for i in range(int(a),int(b)+1)]
                elif len(a)==1 and len(b)==1:indexes=[chr(i) for i in range(ord(a),ord(b)+1)]
                else:raise ValueError()
            except ValueError:raise ParseIssue(f'Invalid dimIndex `{idx}`')
        else:indexes=[idx]
        if len(indexes)!=dim:
            raise ParseIssue(f'dimIndex tag must contain {dim} indexes, found {len(indexes)}')
        if '%s' not in out['name']:
            raise ParseIssue(f"Name `{out['name']}` in tag `{n.tag}` is missing a %s placeholder")
        out.update(dim=dim,dimIncrement=inc,dimIndex=indexes,dimName=n.get('dimName'))
        ia=n.child('dimArrayIndex')
        if ia:out['dimArrayIndex']=self.enum_values(ia)

    def common(self,n):
        out={'kind':n.tag,'name':self.name(n),'node':n}
        for key in ('description','displayName','derivedFrom'):
            v=n.get(key)
            if v is not None:out[key]=v
        if 'derivedFrom' in n.attrs:out['derivedFrom']=n.attrs['derivedFrom']
        return out

    def constraint(self, n):
        el=n.child('writeConstraint')
        if el is None:return None
        ran=el.child('range')
        if ran:return {'minimum':self.num(ran,'minimum',required=True,bits=64),'maximum':self.num(ran,'maximum',required=True,bits=64)}
        if el.child('useEnumeratedValues') is not None:return {'useEnumeratedValues':self.boolean(el,'useEnumeratedValues')}
        if el.child('writeAsRead') is not None:return {'writeAsRead':self.boolean(el,'writeAsRead')}
        return {}

    def effects(self,n,out):
        for key in ('modifiedWriteValues','readAction'):
            v=self.enum(n,key)
            if v is not None:out[key]=v
        c=self.constraint(n)
        if c is not None:out['writeConstraint']=c

    def field(self,n):return self.entity(n,self._field)
    def _field(self,n):
        out=self.common(n)
        for key in ('access',):
            v=self.enum(n,key)
            if v is not None:out[key]=v
        if n.child('bitOffset') is not None:
            off=self.num(n,'bitOffset',required=True)
            width=self.num(n,'bitWidth',required=True)
        elif n.child('lsb') is not None:
            off=self.num(n,'lsb',required=True)
            msb=self.num(n,'msb',required=True)
            width=(msb-off+1)&0xffffffff
        elif n.child('bitRange') is not None:
            s=n.get('bitRange');m=re.fullmatch(r'\[\s*(\d+)\s*:\s*(\d+)\s*\]',s)
            if not m:raise ParseIssue(f'Invalid bitRange `{s}`')
            msb,off=map(int,m.groups());width=(msb-off+1)&0xffffffff
        elif 'derivedFrom' in out:
            off=width=None
        else:
            raise ParseIssue('Expected a <bitOffset> tag, found none')
        if width==0:raise ParseIssue('`BitRange error: bitRange width of 0 does not make sense')
        if off is not None:out.update(bitOffset=off,bitWidth=width)
        self.effects(n,out)
        self.dims(n,out)
        es=n.all('enumeratedValues')
        if es:out['enumeratedValues']=[self.enum_values(e) for e in es]
        return out

    def enum_values(self,n):return self.entity(n,self._enum_values)
    def _enum_values(self,n):
        out={'name':n.get('name')}
        if 'derivedFrom' in n.attrs:out['derivedFrom']=n.attrs['derivedFrom']
        usage=self.enum(n,'usage')
        if usage is not None:out['usage']=usage
        vals=[]
        for el in n.all('enumeratedValue'):
            def value(e):
                v={'name':self.name(e)}
                if e.get('description') is not None:v['description']=e.get('description')
                x=self.num(e,'value',bits=64)
                default=self.boolean(e,'isDefault')
                if x is not None:v['value']=x
                if default is not None:v['isDefault']=default
                if x is None and default is not True:raise ParseIssue('`EnumeratedValue error: EnumeratedValue must have a value or be the default')
                return v
            vals.append(self.entity(el,value))
        out['values']=vals
        return out

    def register(self,n):return self.entity(n,self._register)
    def _register(self,n):
        out=self.common(n);out.update(self.props(n))
        out['addressOffset']=self.num(n,'addressOffset',required=True)
        for key in ('alternateGroup','alternateRegister','dataType'):
            if n.get(key) is not None:out[key]=n.get(key)
        self.effects(n,out);self.dims(n,out)
        fields=n.child('fields')
        if fields is not None:out['fields']=[self.field(f) for f in fields.all('field')]
        return out

    def cluster(self,n):return self.entity(n,self._cluster)
    def _cluster(self,n):
        out=self.common(n);out.update(self.props(n))
        out['addressOffset']=self.num(n,'addressOffset',required=True)
        self.dims(n,out)
        regs=[]
        for c in n.children:
            if c.tag=='register':regs.append(self.register(c))
            elif c.tag=='cluster':regs.append(self.cluster(c))
        if regs:out['registers']=regs
        return out

    def interrupt(self,n):
        def f(n):
            out=self.common(n);out['value']=self.num(n,'value',required=True)
            return out
        return self.entity(n,f)

    def peripheral(self,n):return self.entity(n,self._peripheral)
    def _peripheral(self,n):
        out=self.common(n);out.update(self.props(n))
        out['baseAddress']=self.num(n,'baseAddress',required=True,bits=64)
        for key in ('groupName','headerStructName','prependToName','appendToName'):
            if n.get(key) is not None:out[key]=n.get(key)
        self.dims(n,out)
        out['interrupt']=[self.interrupt(i) for i in n.all('interrupt')]
        regs=n.child('registers')
        if regs is not None:
            out['registers']=[self.register(r) if r.tag=='register' else self.cluster(r) for r in regs.children if r.tag in ('register','cluster')]
        return out

    def cpu(self,n):
        def f(n):
            out=self.common(n)
            for tag in ('revision','endian'):out[tag]=self.required(n,tag)
            for tag in ('mpuPresent','fpuPresent'):out[tag]=self.boolean(n,tag,required=True)
            out['nvicPrioBits']=self.num(n,'nvicPrioBits',required=True)
            out['vendorSystickConfig']=self.boolean(n,'vendorSystickConfig',required=True)
            return out
        return self.entity(n,f)

    def device(self,n):
        def f(n):
            out=self.common(n)
            if n.child('cpu') is not None:out['cpu']=self.cpu(n.child('cpu'))
            out.update(self.props(n))
            for k in ('version','vendor','vendorID','headerSystemFilename','licenseText'):
                if n.get(k) is not None:out[k]=n.get(k)
            ps=n.child('peripherals')
            if ps is None:raise ParseIssue('Expected a <peripherals> tag, found none')
            out['peripherals']=[self.peripheral(p) for p in ps.all('peripheral')]
            if not out['peripherals']:raise ParseIssue('`Device error: Device must contain at least one peripheral')
            return out
        return self.entity(n,f)


def parse_xml(data, strict=False):
    root=xml_tree(data)
    if root is None or root.tag!='device':
        raise Failure('Error parsing SVD XML file',['Expected a <device> tag, found none'])
    try:return Reader(strict).device(root)
    except ParseIssue as e:raise Failure('Error parsing SVD XML file',e.messages)
PY
