"""Small CMSIS-SVD data reader and validation layer.

The model keeps optional properties distinct from explicit zeroes, and retains
source positions so that diagnostics can explain nested register descriptions.
"""
from dataclasses import dataclass, field as dc_field
import re
import xml.parsers.expat as expat


class Failure(Exception):
    def __init__(self, title, causes=()):
        self.title = title
        self.causes = list(causes)
        super().__init__(title)


class ParseIssue(Exception):
    def __init__(self, messages, nested=False):
        self.messages = messages if isinstance(messages, list) else [messages]
        self.nested = nested


@dataclass
class Node:
    tag: str
    attrs: dict = dc_field(default_factory=dict)
    children: list = dc_field(default_factory=list)
    text: str = ''
    line: int = 1
    col: int = 1

    def child(self, tag):
        return next((n for n in self.children if n.tag == tag), None)

    def all(self, tag):
        return [n for n in self.children if n.tag == tag]

    def get(self, tag, default=None):
        n = self.child(tag)
        return n.text.strip() if n is not None else default


def xml_tree(data):
    roots = []
    stack = []
    parser = expat.ParserCreate()
    def start(tag, attrs):
        n = Node(tag.split(':')[-1], attrs, line=parser.CurrentLineNumber,
                 col=parser.CurrentColumnNumber + 1)
        if stack:
            stack[-1].children.append(n)
        else:
            roots.append(n)
        stack.append(n)
    def end(tag):
        stack.pop()
    def text(t):
        if stack:
            stack[-1].text += t
    parser.StartElementHandler = start
    parser.EndElementHandler = end
    parser.CharacterDataHandler = text
    try:
        parser.Parse(data, True)
    except expat.ExpatError as e:
        line, col = e.lineno, e.offset + 1
        msg = str(e).split(': line')[0]
        if 'no element found' in msg and not roots:
            msg = 'the document does not have a root node'
        elif 'syntax error' in msg or 'invalid token' in msg:
            msg = f'unknown token at {line}:{col}'
        elif 'no element found' in msg:
            tag = stack[-1].tag if stack else (roots[-1].tag if roots else 'device')
            msg = f'the root node was opened but never closed'
        elif 'mismatched tag' in msg:
            source = data.decode('utf-8', 'replace') if isinstance(data, bytes) else data
            rows = source.splitlines()
            tail = rows[line-1][col-1:] if line <= len(rows) else ''
            m = re.search(r'</([^>]+)>', tail)
            found = m.group(1) if m else ''
            expected = stack[-1].tag if stack else ''
            msg = f"expected '{expected}' tag, not '{found}' at {line}:{col}"
        elif 'junk after document element' in msg:
            msg = f'unknown token at {line}:{col}'
        else:
            msg = f'{msg} at {line}:{col}'
        raise Failure('Error parsing SVD XML file', [msg])
    return roots[0] if roots else None


ENUMS = {
    'access': ('read-only','write-only','read-write','writeOnce','read-writeOnce'),
    'modifiedWriteValues': ('oneToClear','oneToSet','oneToToggle','zeroToClear','zeroToSet','zeroToToggle','clear','set','modify'),
    'readAction': ('clear','set','modify','modifyExternal'),
    'usage': ('read','write','read-write'),
    'endian': ('little','big','selectable','other'),
}
PROP_NUM = ('size','resetValue','resetMask')
PROP_STR = ('access',)


class Reader:
    def __init__(self, strict=False):
        self.strict = strict

    def parsing(self, n):
        name = n.get('name')
        return f'Parsing {n.tag} `{name}` at {n.line}:{n.col}' if name is not None else f'Parsing unknown {n.tag} at {n.line}:{n.col}'

    def context(self, n):
        name = n.get('name')
        return f'In {n.tag} `{name}`' if name is not None else f'In unknown {n.tag}'

    def entity(self, n, func):
