            k,p,c,s=xs
            c={'p':'pascal','c':'constant','s':'snake','':'unchanged'}.get(c,c)
            if c not in ('pascal','constant','snake','unchanged'):c='unchanged'
            self.formats[k]=(c,p,s)

    def __call__(self,name,kind):
        case,pre,suf=self.formats[kind]
        name=plain_name(name)
        if case=='snake':name=snake(name)
        elif case=='constant':name=snake(name).upper()
