                    if not cpu.get('mpuPresent'):core.remove('MPU')
                s+='pub use cortex_m::peripheral::Peripherals as CorePeripherals; pub use cortex_m::peripheral::{'+', '.join(core)+',}; '
        if self.c.get('reexport_interrupt') and self.c['target']!='none':
