            out,rs,ws=self.field(f,r,rd,wr,rb,spec)
            s+=out;methods_r.extend(rs);methods_w.extend(ws)
            if readable(f.get('access')) and not f.get('readAction'):
                if 'dim' in f:
                    debug_fields.extend(self.n(f['name'].replace('%s',i),'field_accessor') for i in f['dimIndex'])
                else:debug_fields.append(self.n(f['name'],'field_accessor'))
            mw=f.get('modifiedWriteValues')
