                if mw in ('oneToSet','oneToClear','oneToToggle'):one|=mask
        if methods_r:s+='impl R { '+''.join(methods_r)+' } '
        debug=self.c.get('impl_debug') or fs is None
        if debug:
            feat=self.c.get('impl_debug_feature')
            if feat:s+=attr('cfg(feature = '+quote(feat)+')')
            if not rd or r.get('readAction'):
                s+=f'impl core::fmt::Debug for crate::generic::Reg<{spec}> {{ fn fmt(&self, f: &mut core::fmt::Formatter<\'_>) -> core::fmt::Result {{ write!(f, "(not readable)") }} }} '
            elif fs is None:
