                s+='impl core::fmt::Debug for R { fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result { '+body+' } } '
        if wr:s+='impl W { '+''.join(methods_w)+' } '
        s+=doc(desc+'\n\n'+self.api_doc(r,True))+f'pub struct {spec}; impl crate::RegisterSpec for {spec} {{ type Ux = {ux}; }} '
