            title=f'Peripheral access API for {self.d["name"].upper()} microcontrollers (generated using svd2rust v{VERSION})\n\nYou can find an overview of the generated API [here].\n\nAPI features to be included in the [next] svd2rust release can be generated by cloning the svd2rust [repository], checking out the above commit, and running `cargo doc --open`.\n\n[here]: https://docs.rs/svd2rust/0.37.1/svd2rust/#peripheral-api\n[next]: https://github.com/rust-embedded/svd2rust/blob/master/CHANGELOG.md#unreleased\n[repository]: https://github.com/rust-embedded/svd2rust'
            s+='#![doc = '+quote(title)+'] '
            if not self.c.get('make_mod'):
                s+='#![allow(non_camel_case_types)] #![allow(non_snake_case)] #![no_std] #![cfg_attr(docsrs, feature(doc_cfg))] '
        if self.c['target']=='cortex-m':
            cpu=self.d.get('cpu')
            if cpu:
                s+=doc('Number available in the NVIC for configuring priority',True)+f'pub const NVIC_PRIO_BITS: u8 = {cpu["nvicPrioBits"]}; '
            if self.c.get('reexport_core_peripherals'):
                core=['CBP','CPUID','DCB','DWT','FPB','FPU','ITM','MPU','NVIC','SCB','SYST','TPIU']
                if cpu:
