    def collect_irqs(self):
        by_value={}
        for p in self.d['peripherals']:
            for ir in p.get('interrupt',[]):
                val=ir['value']
                if val in by_value:
                    # Multiple peripherals frequently name a shared vector.
                    continue
                ir=ir.copy();ir['_features']=self.feature(p);by_value[val]=ir
        self.irq=[by_value[k] for k in sorted(by_value)]

    def interrupt_code(self):
        self.collect_irqs()
        t=self.c['target'];irs=self.irq;s=''
        if t=='riscv' and self.settings.get('riscv_config') is not None:
            self.log('warn','No base RISC-V ISA specified in settings file.','svd2rust::config::riscv')
            self.log('warn','If your target supports vectored mode, you must specify the base ISA.','svd2rust::config::riscv')
            self.log('warn','Otherwise, `riscv-rt` macros will not provide start trap routines to core interrupt handlers','svd2rust::config::riscv')
            return static_data.RISCV_BASIC
        if t=='riscv':
            self.log('warn','No settings file provided for RISC-V target. Using legacy interrupts rendering','svd2rust::generate::device')
            self.log('warn','Please, consider migrating your PAC to riscv 0.12.0 or later','svd2rust::generate::device')
        self.log('debug','Rendering interrupts','svd2rust::generate::device')
        if t in ('cortex-m','msp430','riscv','xtensa-lx'):
            abi='msp430-interrupt' if t=='msp430' else 'C'
            un='unsafe ' if self.c.get('edition')=='2024' else ''
            s+=attr('cfg(feature = "rt")')+f'{un}extern {quote(abi)} {{ '
            for ir in irs:s+=self.cfg(ir['_features'])+f'fn {self.n(ir["name"],"interrupt")}(); '
            s+='} '+attr('doc(hidden)')+attr('repr(C)')+'pub union Vector { '
            s+=('pub ' if t in ('riscv','xtensa-lx') else '')+f'_handler: unsafe extern {quote(abi)} fn(), '
            s+=('pub ' if t=='riscv' else '')+'_reserved: '+{'riscv':'usize','msp430':'u16'}.get(t,'u32')+', } '
            s+=attr('cfg(feature = "rt")')+attr('doc(hidden)')
            section=self.c.get('interrupt_link_section')
            if section is None and t in ('cortex-m','msp430'):section='.vector_table.interrupts'
            if section is not None:s+=self.unsafe_attr('link_section = '+quote(section))
            s+=self.unsafe_attr('no_mangle')
            if t=='msp430':s+=attr('used')
            name='__EXTERNAL_INTERRUPTS' if t=='riscv' else '__INTERRUPTS'
            count=irs[-1]['value']+1 if irs else 0
            s+=f'pub static {name}: [Vector; {count}] = ['
            lookup={i['value']:i for i in irs}
            if count>100000:raise Failure('Error rendering device',['interrupt number is too large'])
            for j in range(count):
                ir=lookup.get(j)
                if ir is None:s+='Vector { _reserved: 0 }, '
                else:
                    fs=ir['_features']
                    if fs:
                        if len(fs)==1:cf='feature = '+quote(fs[0])
                        else:cf='all('+''.join('feature = '+quote(f)+',' for f in fs)+')'
                        s+=attr('cfg(not('+cf+'))')+'Vector { _reserved: 0 }, '+self.cfg(fs)
