            s+=']; '
        if t in ('riscv','none','mips'):
            if not irs:return s
            s+=attr('doc(hidden)')+'pub mod interrupt { '
        d='Enumeration of all the interrupts.'
        if t=='msp430':d+=' This enum is seldom used in application or library crates. It is present primarily for documenting the device\'s implemented interrupts.'
        s+=doc(d,True)
        if self.c.get('impl_defmt'):s+=attr('cfg_attr(feature = '+quote(self.c['impl_defmt'])+', derive(defmt::Format))')
        s+=attr('derive(Copy, Clone, Debug, PartialEq, Eq)')
        if irs:s+=attr('repr(u16)')
        s+='pub enum Interrupt { '
        for ir in irs:
            s+=doc(str(ir['value'])+' - '+description(ir.get('description',ir['name'])))
            s+=self.cfg(ir['_features'])+f'{self.n(ir["name"],"interrupt")} = {ir["value"]}, '
        s+='} '
        if t=='cortex-m':
            s+='unsafe impl cortex_m::interrupt::InterruptNumber for Interrupt { '+attr('inline(always)')+'fn number(self) -> u16 { '
            s+='self as u16' if irs else 'match self { }'
            s+=' } } '
        elif t!='msp430':
            ty='u16' if t=='xtensa-lx' else 'u8'
            s+=doc(' TryFromInterruptError',True)+attr('derive(Debug, Copy, Clone)')+'pub struct TryFromInterruptError(()); impl Interrupt { '
            s+=doc(' Attempt to convert a given value into an `Interrupt`',True)+attr('inline')+f'pub fn try_from(value: {ty}) -> Result<Self, TryFromInterruptError> {{ match value {{ '
            for ir in irs:s+=self.cfg(ir['_features'])+f'{ir["value"]} => Ok(Interrupt::{self.n(ir["name"],"interrupt")}), '
            s+='_ => Err(TryFromInterruptError(())), } } } '
        if t in ('riscv','none','mips'):
            if t=='riscv':s+=static_data.RISCV_MACRO+' '
            s+='} pub use self::interrupt::Interrupt; '
        return s

    def reg_size(self,r):
        if r['kind']=='cluster':
            size=0
            for x in r.get('registers',[]):
                z=self.reg_size(x);z=(x.get('dim',1)-1)*x.get('dimIncrement',z)+z
                size=max(size,x['addressOffset']+z)
            if self.c.get('max_cluster_size') and 'dim' in r:size=max(size,r['dimIncrement'])
            return size
        name=r['name']
        if 'size' not in r:raise ValueError(f'Register {name} has no `size` field')
        return int_bits(r['size'])//8

    def validate_sizes(self,p):
        def walk(r):
            try:self.reg_size(r)
            except ValueError as e:
                raise Failure('Error rendering device',[f"can't render peripheral '{p['name']}', group '{p.get('groupName','No group name')}'",f"can't render register '{r['name']}'",str(e)])
            for sub in r.get('registers',[]):walk(sub)
        for r in p.get('registers',[]):walk(r)

    def block(self,container,ty='RegisterBlock'):
        regs=container.get('registers',[])
        members=[];methods=[];items=[]
        for r in regs:
            name=self.reg_name(r);kind=r['kind'];rty=self.n(name,'register' if kind=='register' else 'cluster')
            field=self.n(name,'register_accessor' if kind=='register' else 'cluster_accessor')
            size=self.reg_size(r);off=r['addressOffset']
            arr='dim' in r
            keep=arr and self.c.get('keep_list') and '[%s]' not in r['name']
            if keep:
                for i,index in enumerate(r['dimIndex']):
                    nm=self.n(r['name'].replace('%s',index),'register_accessor' if kind=='register' else 'cluster_accessor')
                    items.append(dict(r=r,field=nm,ty=rty,off=off+i*r['dimIncrement'],size=size,array=False,docoff=off))
            else:
                items.append(dict(r=r,field=field,ty=rty,off=off,size=size,array=arr,docoff=off))
        items.sort(key=lambda e:e['off'])
        # Connected overlapping ranges are represented by a reserved byte region
        # and typed pointer accessors instead of Rust union fields.
        groups=[]
        for item in items:
            span=item['size']
            if item['array']:span=(item['r']['dim']-1)*item['r']['dimIncrement']+span
            item['end']=item['off']+span
            if groups and item['off']<groups[-1]['end']:
                groups[-1]['items'].append(item);groups[-1]['end']=max(groups[-1]['end'],item['end'])
            else:groups.append({'off':item['off'],'end':item['end'],'items':[item]})
        position=0;index=0
        for group in groups:
            its=group['items'];off=group['off']
            if off>position:members.append(f'_reserved{index}: [u8; {hexnum(off-position)}],')
            if len(its)>1:
                first=its[0]
                members.append(f'_reserved_{index}_{first["field"]}: [u8; {hexnum(group["end"]-off)}],')
                for it in reversed(its):methods.append(self.block_accessor(it,True))
                position=group['end'];index+=len(its)
            else:
                it=its[0];r=it['r'];array=it['array']
                if array and r['dimIncrement']!=it['size']:
                    members.append(f'{it["field"]}: (),');position=off
                else:
                    t=f'[{it["ty"]}; {r["dim"]}]' if array else it['ty']
                    members.append(f'{it["field"]}: {t},');position=it['end']
                methods.append(self.block_accessor(it,False));index+=1
        if container.get('kind')=='cluster' and self.c.get('max_cluster_size') and 'dim' in container:
            pad=container['dimIncrement']-position
            if pad>0:members.append(f'_reserved_end: [u8; {hexnum(pad)}],')
        s=attr('repr(C)')
        if self.c.get('impl_debug'):
            feat=self.c.get('impl_debug_feature')
            s+=attr('cfg_attr(feature = '+quote(feat)+', derive(Debug))') if feat else attr('derive(Debug)')
        if ty=='RegisterBlock':s+=doc('Register block')
        else:
            s+=doc(description(container.get('description','')))
            alias=base_name(container['name'])
            if alias!=ty:s+=attr('doc(alias = '+quote(alias)+')')
        s+=f'pub struct {ty} {{ '+''.join(members)+f' }} impl {ty} {{ '+''.join(methods)+' } '
        for r in regs:
            if r.get('_alias'):
                src=r['_alias'];nm=self.reg_name(r);snm=self.reg_name(src)
                category='cluster' if r['kind']=='cluster' else 'register'
                typ=self.n(nm,category);orig=self.n(snm,category)
                mod=self.n(nm,category+'_mod');smod=self.n(snm,category+'_mod')
                # Use a relative path when the base is in another container.
                path=''
                if r.get('_parent_path')!=src.get('_parent_path'):
                    path='crate::'+'::'.join(self.n(x,'peripheral_mod' if i==0 else 'cluster_mod') for i,x in enumerate(src['_parent_path']))+'::'
                s+=f'pub use {path}{orig} as {typ}; pub use {path}{smod} as {mod}; '
            elif r['kind']=='cluster':s+=self.cluster(r)
            else:s+=self.register(r)
        return s

    def block_accessor(self,it,overlap):
        r=it['r'];off=it['off'];field=it['field'];ty=it['ty'];array=it['array']
        text=description(r.get('description'))
        a=hexnum(it['docoff'],zero='0x00')
        if array:a+='..'+hexnum(it['docoff']+r['dim']*it['size'],zero='0x00')
        d=a+' - '+text
        s=doc(d)
        if not array:
            val=ptr(off) if overlap else '&self.'+field
            return s+attr('inline(always)')+f'pub const fn {field}(&self) -> &{ty} {{ {val} }} '
        indexes=r['dimIndex'];default=indexes==[str(i) for i in range(r['dim'])]
        if not default:
            first=r['name'].replace('%s',indexes[0])
            s+=doc('')+doc(f'<div class="warning">`n` is the index of register in the array. `n == 0` corresponds to `{first}` register.</div>')
        gapped=r['dimIncrement']!=it['size'] or overlap
        if gapped:
            val=ptr(off,r['dimIncrement'])
            body=attr('allow(clippy::no_effect)')+f'[(); {r["dim"]}][n]; '+val
        else:body='&self.'+field+'[n]'
        s+=attr('inline(always)')+f'pub const fn {field}(&self, n: usize) -> &{ty} {{ {body} }} '
        s+=doc('Iterator for array of:')+doc(d)+attr('inline(always)')
        val=f'(0 .. {r["dim"]}).map(move |n| {ptr(off,r["dimIncrement"])})' if gapped else f'self.{field}.iter()'
        s+=f'pub fn {field}_iter(&self) -> impl Iterator<Item = &{ty}> {{ {val} }} '
        if not default and '[%s]' not in r['name']:
            for i,ix in enumerate(indexes):
                nm=self.n(r['name'].replace('%s',ix),'register_accessor' if r['kind']=='register' else 'cluster_accessor')
                s+=doc(hexnum(off+i*r['dimIncrement'],zero='0x00')+' - '+text)+attr('inline(always)')
                s+=f'pub const fn {nm}(&self) -> &{ty} {{ self.{field}({i}) }} '
        return s

    def cluster(self,r):
        name=self.reg_name(r);ty=self.n(name,'cluster');mod=self.n(name,'cluster_mod');desc=description(r.get('description'))
        return doc(desc)+f'pub use self::{mod}::{ty}; '+doc('Cluster',True)+doc(desc)+f'pub mod {mod} {{ '+self.block(r,ty)+' } '

    def access(self,r):
        ac=r.get('access')
        if ac is not None:return readable(ac),writable(ac)
        fs=r.get('fields')
        if fs is None:return True,True
        if not fs:return True,False
        return any(readable(f.get('access')) for f in fs),any(writable(f.get('access')) for f in fs)

    def action_warning(self,a,kind):
        if not a:return ''
        words={'clear':'<b>cleared</b> (set to zero) following a read operation.',
               'set':'<b>set</b> (set to ones) following a read operation.',
               'modify':'<b>modified</b> in some way after a read operation.',
               'modifyExternal':'<b>modified</b> in some way after a read operation.'}
        return f'\n\n<div class="warning">The {kind} is '+words.get(a,words['modify'])+'</div>'

    def api_doc(self,r,local=False):
        rd,wr=self.access(r);mod=self.n(self.reg_name(r),'register_mod')
        crate=self.settings.get('crate_path') or 'crate'
        path=crate+'::Reg::'
        s='You can '
        parts=[]
        def link(method):return '[`'+method+'`]('+path+method+')'
        def struct(which):return f'[`{mod}::{which}`]'+(f'({which})' if local else '')
        if rd:parts.append('You can '+link('read')+' this register and get '+struct('R')+'.')
        if wr:
            ms=['reset','write','write_with_zero'] if 'resetValue' in r else ['write_with_zero']
            parts.append('You can '+', '.join(map(link,ms))+' this register using '+struct('W')+'.')
        if rd and wr:parts.append('You can also '+link('modify')+' this register.')
        s=' '.join(parts)+' See [API](https://docs.rs/svd2rust/#read--modify--write-api).'
        s+=self.action_warning(r.get('readAction'),'register')
        return s

    def register(self,r):
        name=self.reg_name(r);ty=self.n(name,'register');mod=self.n(name,'register_mod');spec=self.n(name,'register_spec')
        rb=int_bits(r['size']);ux='u'+str(rb);rd,wr=self.access(r)
        desc=description(r.get('description'))
        if r.get('description') is None:
            for _ in range(2):self.log('warn','Missing description for register '+r['name'],'svd2rust::generate::register')
        access='rw' if rd and wr else 'r' if rd else 'w'
        d=f'{name} ({access}) register accessor: {desc}\n\n'+self.api_doc(r)+'\n\nFor information about available fields see [`mod@'+mod+'`] module'
        if self.settings.get('html_url'):
            d+='\n\nSee register [structure]('+self.settings['html_url'].rstrip('/')+'/#'+'.'.join(r['_path'])+')'
        s=doc(d)
        if name!=ty:s+=attr('doc(alias = '+quote(name)+')')
        s+=f'pub type {ty} = crate::Reg<{mod}::{spec}>; '+doc(desc)+f'pub mod {mod} {{ '
        if rd:s+=doc(f'Register `{r["name"]}` reader')+f'pub type R = crate::R<{spec}>; '
        if wr:s+=doc(f'Register `{r["name"]}` writer')+f'pub type W = crate::W<{spec}>; '
        fs=r.get('fields')
        methods_r=[];methods_w=[];debug_fields=[]
        fields=sorted(fs or [],key=lambda f:f.get('bitOffset',0))
        zero=one=0
        for f in fields:
            if f['name'].lower()=='reserved':continue
            out,rs,ws=self.field(f,r,rd,wr,rb,spec)
            s+=out;methods_r.extend(rs);methods_w.extend(ws)
            if readable(f.get('access')) and not f.get('readAction'):
                if 'dim' in f:
                    debug_fields.extend(self.n(f['name'].replace('%s',i),'field_accessor') for i in f['dimIndex'])
                else:debug_fields.append(self.n(f['name'],'field_accessor'))
            mw=f.get('modifiedWriteValues')
            if writable(f.get('access')) and wr:
