            else:
                body='f.debug_struct('+quote(r['name'])+')'+''.join('.field('+quote(f)+', &self.'+f+'())' for f in debug_fields)+'.finish()'
                s+='impl core::fmt::Debug for R { fn fmt(&self, f: &mut core::fmt::Formatter) -> core::fmt::Result { '+body+' } } '
        if wr:s+='impl W { '+''.join(methods_w)+' } '
        s+=doc(desc+'\n\n'+self.api_doc(r,True))+f'pub struct {spec}; impl crate::RegisterSpec for {spec} {{ type Ux = {ux}; }} '
        if rd:s+=doc(f'`read()` method returns [`{mod}::R`](R) reader structure')+f'impl crate::Readable for {spec} {{ }} '
        if wr:
            safety='Safe' if self.full_range(r.get('writeConstraint'),r['size']) else 'Unsafe'
            s+=doc(f'`write(|w| ..)` method takes [`{mod}::W`](W) writer structure')+f'impl crate::Writable for {spec} {{ type Safety = crate::{safety}; '
            if zero:s+=f'const ZERO_TO_MODIFY_FIELDS_BITMAP: {ux} = {hexnum(zero)}; '
            if one:s+=f'const ONE_TO_MODIFY_FIELDS_BITMAP: {ux} = {hexnum(one)}; '
            s+='} '
        if 'resetValue' in r:
            reset=r['resetValue']
            s+=doc(f'`reset()` method sets {r["name"]} to value {hexnum(reset)}')+f'impl crate::Resettable for {spec} {{ '
            if reset:s+=f'const RESET_VALUE: {ux} = {hexnum(reset)}; '
            s+='} '
        s+='} '
        return s

    def full_range(self,c,width):
        return c is not None and c.get('minimum')==0 and c.get('maximum')==(1<<width)-1

    def field_read_expr(self,f,rb,offset=None):
        width=f['bitWidth'];off=f['bitOffset'] if offset is None else offset;fb=int_bits(width)
        value='self.bits'
        if off!=0:value=f'(self.bits >> {off})'
        if width==1:
            return f'({value} & 1) != 0'
        if width!=rb:value=f'({value} & {hexnum((1<<min(width,64))-1) if width>3 else str((1<<width)-1)})'
        # Shifted/masked fields of the same raw type do not need a cast.
        if fb!=rb:value+=' as u'+str(fb)
        return value

    def field_doc_name(self,f):
        if 'dim' not in f:return f['name']
        idx=f['dimIndex'];contiguous=False
        if idx and all(x.isdigit() for x in idx):
            contiguous=[str(i) for i in range(int(idx[0]),int(idx[-1])+1)]==idx
        if contiguous:v=idx[0]+'-'+idx[-1]
        else:v=','.join(idx)
        return f['name'].replace('[%s]','('+v+')').replace('%s','('+v+')')

    def field(self,f,r,rd,wr,rb,spec):
