        acc=self.n(name,'field_accessor');width=f.get('bitWidth',1);off=f.get('bitOffset',0);fb=int_bits(width);ux='bool' if width==1 else 'u'+str(fb)
        rd=rd and readable(f.get('access'));wr=wr and writable(f.get('access'))
