            if er and (rd or writeset is readset):s+=self.enum_definition(er,f,r)
        if wr and writeset:
            if writeset is readset:ew=er
            else:ew=self.enum_info(writeset,f,r,'enum_write_name')
        if rd:
            d='Field `'+dn+'` reader'+(' - '+desc if desc else '')+self.action_warning(f.get('readAction'),'field')
            params=er['type'] if er else (ux if width!=1 and ux!='u8' else '')
            s+=doc(d)+f'pub type {rt} = crate::'+('BitReader' if width==1 else 'FieldReader')+('<'+params+'>' if params else '')+'; '
            if er:s+=self.enum_reader(er,rt,width)
