        if msg.startswith('`Device error:'):
            raise Failure(msg,[msg.split(': ',1)[1]])
        if msg.startswith('`') and ': ' in msg:raise Failure(msg,[msg.split(': ',1)[1]])
        raise Failure(title,[msg+loc()])
