"""Readers for the JSON and the indentation-based YAML interchange formats."""
import ast
import json
import re
from model import Node, Reader, ParseIssue, Failure

class YamlError(Exception):
    pass


def yaml_scalar(s):
    s=s.strip()
    if not s:return None
    if s[0:1] in ('"',"'"):
        try:return json.loads(s) if s[0]=='"' else s[1:-1].replace("''", "'")
        except Exception:return s[1:-1]
    if s in ('null','Null','NULL','~'):return None
    if s.lower() in ('true','false'):return s.lower()=='true'
    if s.startswith('[') and s.endswith(']'):
        return [yaml_scalar(x) for x in split_inline(s[1:-1])] if s[1:-1].strip() else []
    if s.startswith('{') and s.endswith('}'):
        out={}
        for item in split_inline(s[1:-1]):
            if ':' in item:
                a,b=item.split(':',1);out[yaml_scalar(a)]=yaml_scalar(b)
        return out
    if re.match(r'^[+-]?(?:0x[0-9a-fA-F_]+|0o[0-7_]+|0b[01_]+|\d[\d_]*)$',s):
        try:return int(s.replace('_',''),0 if s.lstrip('+-').startswith(('0x','0o','0b')) else 10)
        except ValueError:pass
    if re.match(r'^[+-]?\d+\.\d+(?:[eE][+-]?\d+)?$',s):
        try:return float(s)
        except ValueError:pass
    return s


def split_inline(s):
    pieces=[];start=0;level=0;quote=None
    for i,ch in enumerate(s):
        if quote:
            if ch==quote and (i==0 or s[i-1]!='\\'):quote=None
        elif ch in ('"',"'"):quote=ch
        elif ch in '[{(':level+=1
        elif ch in ']})':level-=1
        elif ch==',' and level==0:pieces.append(s[start:i].strip());start=i+1
    if s[start:].strip():pieces.append(s[start:].strip())
    return pieces


def yaml_load(text):
    if text.strip().startswith(('{','[')):
        try:return json.loads(text)
        except Exception:return yaml_scalar(text.strip())
    lines=[]
    for no,line in enumerate(text.splitlines()):
        if not line.strip() or line.lstrip().startswith('#') or line.strip() in ('---','...'):continue
        if '\t' in line[:len(line)-len(line.lstrip())]:raise YamlError(f'found character that cannot start any token at line {no+1} column 1')
