def validate_settings(settings, yaml_text=None):
    """Apply the settings schema, while leaving unrecognized keys harmless."""
    import copy
    from urllib.parse import urlsplit, urlunsplit
    settings=copy.deepcopy(settings)
    is_yaml=yaml_text is not None
    def fail(path,message):
        if is_yaml:
            location=''
            key=path.rsplit('.',1)[-1].split('[')[0]
            if path:
                for line,row in enumerate(yaml_text.splitlines(),1):
                    m=re.search(r'\b'+re.escape(key)+r'\s*:\s*',row)
                    if m:
                        location=f' at line {line} column {m.end()+1}';break
            raise Failure('could not parse settings file',[(path+': ' if path else '')+message+location])
        raise Failure('Failed to deserialize value',[message])
    def structure(v,path,name):
        if not isinstance(v,dict):fail(path,'invalid type: '+type_name(v)+', expected struct '+name)
    def string(v,path,expected='a string'):
        if isinstance(v,str):return v
        if is_yaml and isinstance(v,(int,float,bool)):return str(v).lower() if isinstance(v,bool) else str(v)
        fail(path,'invalid type: '+type_name(v)+', expected '+expected)
    def integer(v,path,expected='usize'):
        if not isinstance(v,int) or isinstance(v,bool) or v<0 or v>2**64-1:
            fail(path,'invalid type: '+type_name(v)+', expected '+expected)
        return v
    structure(settings,'','Settings')
    if settings.get('html_url') is not None:
        url=string(settings['html_url'],'html_url','a string representing an URL')
        try:u=urlsplit(url)
        except ValueError:fail('html_url','invalid URL: '+json.dumps(url))
        if not u.scheme:fail('html_url','relative URL without a base: '+json.dumps(url))
        if u.scheme in ('http','https','ftp'):
            if not u.netloc:fail('html_url','empty host: '+json.dumps(url))
            url=urlunsplit((u.scheme.lower(),u.netloc.lower(),u.path or '/',u.query,u.fragment))
        settings['html_url']=url
    if settings.get('crate_path') is not None:settings['crate_path']=string(settings['crate_path'],'crate_path')
    r=settings.get('riscv_config')
    if r is not None:
        structure(r,'riscv_config','RiscvConfig')
        for key in ('core_interrupts','exceptions','priorities','harts'):
            values=r.get(key,[])
            path='riscv_config.'+key
            if not isinstance(values,list):fail(path,'invalid type: '+type_name(values)+', expected a sequence')
            for i,item in enumerate(values):
                ip=path+'['+str(i)+']'
                structure(item,ip,'RiscvEnumItem')
                if 'name' in item:item['name']=string(item['name'],ip+'.name')
                if 'value' in item:item['value']=integer(item['value'],ip+'.value')
                if item.get('description') is not None:item['description']=string(item['description'],ip+'.description')
        for key in ('clint','plic'):
            item=r.get(key)
            if item is None:continue
            path='riscv_config.'+key
            structure(item,path,'RiscvClintConfig' if key=='clint' else 'RiscvPlicConfig')
            for fld in ('name','core_interrupt','hart_id'):
                if item.get(fld) is not None:item[fld]=string(item[fld],path+'.'+fld)
            if 'pub_new' in item and not isinstance(item['pub_new'],bool):fail(path+'.pub_new','invalid type: '+type_name(item['pub_new'])+', expected a boolean')
            if 'mtime_freq' in item:item['mtime_freq']=integer(item['mtime_freq'],path+'.mtime_freq')
        if r.get('base_isa') is not None:r['base_isa']=string(r['base_isa'],'riscv_config.base_isa')
        if r.get('mtvec_align') is not None:r['mtvec_align']=integer(r['mtvec_align'],'riscv_config.mtvec_align')
    return settings
